import java.util.*;

class Solution {
    public List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        dfs(root, res);
        return res;
    }

    private void dfs(TreeNode node, List<Integer> res) {
        if (node == null) return;
        dfs(node.left, res);      // 左
        res.add(node.val);        // 根
        dfs(node.right, res);     // 右
    }
}

import java.util.*;

class Solution {
    public List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;

        // 必须用 || ：cur 空了但栈里还有节点时不能停
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;      // 一路向左
            }
            cur = stack.pop();
            res.add(cur.val);        // 左处理完了，处理根
            cur = cur.right;         // 转向右子树
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public List<Integer> inorderTraversal(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        TreeNode cur = root;

        while (cur != null) {
            if (cur.left == null) {
                res.add(cur.val);       // 没有左子树，直接访问
                cur = cur.right;
            } else {
                // 找左子树里最右的节点（中序前驱）
                TreeNode p = cur.left;
                while (p.right != null && p.right != cur) {
                    p = p.right;
                }
                if (p.right == null) {
                    p.right = cur;      // 建线索
                    cur = cur.left;
                } else {
                    p.right = null;     // 断开线索，恢复原树
                    res.add(cur.val);   // 左子树已遍历完，访问根
                    cur = cur.right;
                }
            }
        }
        return res;
    }
}
